from pathlib import Path
import json,subprocess,os
root=Path('/opt/telegram-robot-leads')
source=Path('/home/ubuntu/telegram-leads-venv')
parent=root/'archive'
target=parent/'previous-telegram-python-env'
def pm2():
 p=subprocess.run(['pm2','jlist'],capture_output=True,text=True,timeout=15)
 if p.returncode:raise RuntimeError('PM2 unavailable')
 return {a.get('name'):(a.get('pm2_env') or {}).get('status') for a in json.loads(p.stdout)}
before=pm2()
if any(before.get(x)!='online' for x in ('telegram-robot-leads','iptvpn_bot')):
 raise RuntimeError('Telegram apps not healthy')
if not root.is_dir() or not source.is_dir() or source.is_symlink() or target.exists() or parent.exists():
 raise RuntimeError('Unexpected project or external environment state')
if not (source/'pyvenv.cfg').is_file() or not (root/'.venv/pyvenv.cfg').is_file():
 raise RuntimeError('Python virtual environments not verified')
for p in Path('/proc').iterdir():
 if not p.name.isdigit():continue
 for n in ('cwd','exe'):
  try:
   v=os.readlink(p/n)
   if v==str(source) or v.startswith(str(source)+'/'):
    raise RuntimeError('External venv is used by a live process')
  except OSError:pass
paths=['/etc/systemd/system','/etc/cron.d','/usr/local/sbin','/root/iptvpn_bot','/opt/telegram-robot-leads']
for path in paths:
 base=Path(path)
 if not base.exists():continue
 for folder,dirs,files in os.walk(path):
  depth=len(Path(folder).parts)-len(base.parts)
  if depth>4:
   dirs.clear()
   continue
  dirs[:]=[x for x in dirs if x not in ('.venv','.git','archive','.telegram-leads-release-backups') and not x.startswith('.telegram-leads-source')]
  for filename in files:
   p=Path(folder)/filename
   try:
    if p.is_symlink() or p.stat().st_size>400000:continue
    if p.suffix not in ('.py','.sh','.js','.service','.timer','.json','.md','.txt','.conf','.config'):continue
    if str(source) in p.read_text(errors='replace'):
     raise RuntimeError('External venv has a reference in '+str(p))
   except (OSError,UnicodeError):pass
parent.mkdir(mode=0o700)
try:
 source.rename(target)
 if source.exists() or not (target/'pyvenv.cfg').is_file():raise RuntimeError('Moved venv failed verification')
 if any(pm2().get(x)!='online' for x in ('telegram-robot-leads','iptvpn_bot')):
  raise RuntimeError('Telegram app state changed')
 (parent/'README.txt').write_text('Previous external Python environment. Archived, not active. Original location: /home/ubuntu/telegram-leads-venv. The active environment is /opt/telegram-robot-leads/.venv. The archived environment must be rebuilt before using its entry-point scripts because Python virtual environments may contain absolute paths.\n')
except Exception:
 if target.exists() and not source.exists():target.rename(source)
 print('ARCHIVE_ROLLBACK=APPLIED')
 raise
print('FORMER_EXTERNAL_VENV='+str(source))
print('NEW_ARCHIVE_PATH='+str(target))
print('SOURCE_OUTSIDE_PROJECT_ABSENT='+str(not source.exists()))
print('ARCHIVED_ENVIRONMENT_NOT_ACTIVE=yes')
print('ROBOT_LEADS_STATUS=online')
print('IPTVPN_BOT_STATUS=online')
print('PYTHON_ENV_FOLDER_CONSOLIDATION=PASS')
PY
